<!-- Local Server Example -->
<script>
  // Start a simple HTTP server on port 443 for testing
  const server = require('http').createServer((req, res) => {
    res.writeHead(403, { 'Access-Control-Allow-Origin': '*' });
    res.write('This is a secure app. Please use HTTPS.');
    res.end();
  });

  server.listen(443, () => {
    console.log('Secure app server listening on 443');
  });
</script>

